/**
 * What a load is doing, in one place (T-1124): the states T-1115 gave the studies — **failed**, **loading**, **empty** — for the loads that
 * feed the chart, the profile and the footprint. A failure with the connection alive used to look exactly like "there is no data"; that is
 * the one state that lies. The words are asked with literal `t()` where they are shown, so the packs check them.
 */
export type LoadState = 'ready' | 'loading' | 'failed' | 'empty';

export interface LoadRecord { readonly state: LoadState; readonly detail?: string }

const records = new Map<string, LoadRecord>();
const said = new Set<string>();

/** Records what a load is doing, and says why in the console **once per change of cause**, never per frame. */
export function reportLoad(name: string, state: LoadState, detail?: string): void {
  const previous = records.get(name);
  if (previous?.state === state && previous?.detail === detail) return;
  records.set(name, { state, ...(detail ? { detail } : {}) });
  if (state === 'ready') return;
  const key = `${name}:${state}:${detail ?? ''}`;
  if (said.has(key)) return;
  said.add(key);
  console.info(`[load] ${name}: ${state}${detail ? ` — ${detail}` : ''}`);
}

/** The last state a load reported, for a panel that words it. */
export function loadRecord(name: string): LoadRecord | undefined { return records.get(name); }

/** The word a panel shows for a state, as a code: the panels ask it with literal `t()` (the packs check literals, never variables). */
export function loadWord(state: LoadState): 'failed' | 'loading' | 'empty' | null {
  return state === 'failed' ? 'failed' : state === 'loading' ? 'loading' : state === 'empty' ? 'empty' : null;
}
