const text = (params: InputValues, id: string, fallback: string): string => typeof params[id] === 'string' ? params[id] as string : fallback;
const number = (params: InputValues, id: string, fallback: number): number => typeof params[id] === 'number' && Number.isFinite(params[id]) ? params[id] : fallback;
const labelOf = (id: string): string => CYCLE_SESSIONS.find(spec => spec.id === id)?.label ?? id;
const LOOKBACK = 500;
/** The chart bar's own size, from its starts: the range's HTF is the step above it (`auto_htfPDA`). */
const chartBar = (bars: readonly Bar[]): number => bars.length > 1 ? bars[1]![0] - bars[0]![0] : 60_000;

/**
 * The session windows of the stretch, reused between frames.
 *
 * Why (T-1238, measured): a thousand hourly bars are forty days, and `cycle-90` has to turn every window boundary into an instant for each of
 * them, so asking again on every frame cost about 10 ms here even with the instants themselves kept — and 310-370 ms before that. The windows
 * tile time every ninety minutes, so the list can only change when the clock crosses one: until then the same answer stands, and it is asked
 * up to a boundary past the chart so a new bar does not throw it away.
 *
 * Only `id`, `variant`, `from` and `to` are read from these — the range a session carries belongs to `cycle-90`, which keeps computing it for
 * its own piece; a cached window's `high`/`low` are as they were when it was asked, and nothing here looks at them.
 */
interface WindowsHeld { readonly days: string; readonly until: number; readonly windows: readonly CycleSession[] }
let windowsHeld: WindowsHeld | null = null;
/** The longest stretch with no window end or start in it: the slots run every ninety minutes (D-19), so nothing changes before that. */
const SESSION_SLOT_MS = 90 * 60_000;

function sessionWindows(chart: readonly Bar[], now: number, zone: CycleZone, end: number): readonly CycleSession[] {
  // The windows are calendar arithmetic on the days the stretch covers, so a pan inside the same days asks the same question: keyed by those days
  // rather than by the first bar, a drag across the chart costs the lookups and not the walk.
  const ask = Math.max(end, now + SESSION_SLOT_MS);
  const from = dayOf(chart[0]![0], zone), to = dayOf(ask, zone);
  const days = `${zone}|${from.y}-${from.mo}-${from.d}|${to.y}-${to.mo}-${to.d}`;
  const held = windowsHeld;
  if (held && held.days === days && now < held.until) return held.windows;
  const windows = cycleSessions(chart, chart[0]![0], ask, now, zone);
  // The next moment the answer can change: the first window end still ahead, or a whole slot when every window of the stretch has closed (the
  // slots tile time, so the next one opens within one).
  let until = now + SESSION_SLOT_MS;
  for (const window of windows) if (window.to > now && window.to < until) until = window.to;
  windowsHeld = windows.length ? { days, until, windows } : null;
  return windows;
}

/** The side a session's window carries: buying in A and M, selling in D and X (`:2852`). */
function sideOfVariant(variant: CycleVariant): 'bull' | 'bear' { return variant === 'A' || variant === 'M' ? 'bull' : 'bear'; }

/**
 * The bubbles of the stretch, oldest first.
 *
 * The bins are cut over the **higher-timeframe candle** that holds each chart bar (`htf`, the Pine's `lastHigh_actual`/`lastLow_actual`,
 * `OEC:772`, `:2761`); with no `htf` the chart bar is binned, which is the Pine's default timeframe (`OEC:159`). Nothing fires before the
 * five hundredth bar: Pine's 500-bar volume average and percentile are `na` there (`GlobalFunctions library:2184`, `:2197-2200`), and the
 * series it reads carries a zero for every bar without a delta (`nz`).
 */
export function bookmapBars(chart: readonly Bar[], ltf: readonly Bar[], now: number, zone: CycleZone, params: { bins: number; mode: string; autoTop: number; manual: number; minVolPct: number }, htf: readonly Bar[] | null = null, tickSize: number | null = null, retention: { mitigated?: boolean; mode?: 'Present' | 'Historic'; last?: number } = {}): BookmapBar[] {
  if (chart.length < 2) return [];
  const barMs = chart[1]![0] - chart[0]![0];
  if (!(barMs > 0)) return [];
  const htfSpan = htf && htf.length >= 2 ? htf[1]![0] - htf[0]![0] : 0;
  let htfIndex = 0;
  const sessions = sessionWindows(chart, now, zone, chart[chart.length - 1]![0] + barMs);
  const bubbles: BookmapBar[] = [];
  // `KL:392-442`: a new delta within five ticks of an active bubble of the same side adds its volume to it instead of opening another,
  // and at most 100 are kept. Without the instrument's tick (`null`) there is no tolerance to compare with, so one bubble a bar is drawn
  // and this says it: a made-up tick would merge bubbles the Pine splits and split the ones it merges.
  const tolerance = typeof tickSize === 'number' && tickSize > 0 ? tickSize * 5 : null;
  const active: number[] = []; // indexes into `bubbles` that may still take volume
  // Every bar's own largest delta — the Pine's `nz(barMaxDelta, 0)` — worked out once, because the threshold reads the whole series and the
  // bubbles read one bar at a time. `absolute` is what that percentile is over.
  const deltas: (DeltaAt | null)[] = [], absolute: number[] = [], sessionOf: (CycleSession | null)[] = [];
  // The lower series is ordered like the chart, so one pointer walks it forward and is never rewound: the `filter` this replaced scanned the
  // whole lower series for every chart bar (30.000 × 1.000 comparisons, plus an array a bar) and that is what froze the page once the warm-up
  // handed the piece a thousand chart bars (T-1238). Cost is now linear in the two series together.
  let ltfIndex = 0;
  // The sub-bars of one chart bar, rewritten in place: `calcBarMaxDelta` only reads them, and an array a bar was most of what the collector had
  // to pick up here (T-1238).
  const sub: Bar[] = [];
  // The sessions are sorted and tile time with no overlap (D-19), so the one holding a bar is found with a pointer that only moves forward,
  // instead of walking all of them — five hundred sessions against a thousand bars — for every bar.
  let sessionIndex = 0;
  // The volume average is a window of the last `LOOKBACK` bars that moves one bar at a time: one volume enters and one leaves, instead of a
  // 500-element `slice` and `map` per chart bar. Same sum, same count, no array.
  let volumeSum = 0;
  for (let index = 0; index < chart.length; index += 1) {
    const bar = chart[index]!;
    const ready = index + 1 >= LOOKBACK; // `ta.sma(volume, 500)` and the 500-bar percentile are `na` before this bar
    const complete = bar[0] + barMs <= now;
    volumeSum += bar[5];
    if (index >= LOOKBACK) volumeSum -= chart[index - LOOKBACK]![5];
    const averageVolume = volumeSum / Math.max(1, Math.min(index + 1, LOOKBACK));
    while (sessionIndex < sessions.length && sessions[sessionIndex]!.to <= bar[0]) sessionIndex += 1;
    const session = sessionIndex < sessions.length && bar[0] >= sessions[sessionIndex]!.from ? sessions[sessionIndex]! : null;
    while (htfSpan > 0 && htfIndex + 1 < htf!.length && htf![htfIndex + 1]![0] <= bar[0]) htfIndex += 1;
    const holder = htfSpan > 0 && htf![htfIndex]![0] <= bar[0] && bar[0] < htf![htfIndex]![0] + htfSpan ? htf![htfIndex]! : null;
    const span = holder ?? bar;
    // The lower bars inside this chart bar, from the pointer: `ltfIndex` only moves forward, and the probe stops at the first bar of the next.
    let at: DeltaAt | null = null;
    if (ready && complete && session && bar[5] >= averageVolume * params.minVolPct / 100) {
      const to = bar[0] + barMs;
      while (ltfIndex < ltf.length && ltf[ltfIndex]![0] < bar[0]) ltfIndex += 1;
      sub.length = 0;
      for (let probe = ltfIndex; probe < ltf.length && ltf[probe]![0] < to; probe += 1) sub.push(ltf[probe]!);
      at = calcBarMaxDelta(span[2], span[3], params.bins, sub);
    }
    deltas.push(at);
    absolute.push(at ? Math.abs(at.delta) : 0);
    sessionOf.push(session);
  }
  // The threshold of `Bar` mode (`GF:2180-2205`): the `100 - AutoTop`th percentile of the last five hundred absolute deltas, for every bar at
  // once. `Manual` mode reads its own number and never asks.
  const percents = params.mode === 'manual' ? null : slidingPercentiles(absolute, LOOKBACK, 100 - params.autoTop);
  for (let index = 0; index < chart.length; index += 1) {
    const at = deltas[index]!, session = sessionOf[index]!;
    // The window decides the side (`RZ_S_Boookmap_Trigger`, `OddEyeCircle:2852`): a bubble only fires when its own delta agrees with the
    // side of the session it is in, so a selling delta inside A/M is not a trigger, and neither is a buying one inside D/X.
    if (!at || !session || at.side !== sideOfVariant(session.variant)) continue;
    const threshold = params.mode === 'manual' ? params.manual : percents![index]!;
    if (!(threshold > 0) || Math.abs(at.delta) < threshold) continue;
    if (tolerance !== null) {
      let merged = false;
      for (const held of active) {
        const kept = bubbles[held]!;
        if (kept.side === at.side && kept.session.id === session.id && Math.abs(kept.price - at.price) <= tolerance) {
          // The Pine adds the new delta to the held volume and recolours it; the price and the bar it sits on do not move.
          bubbles[held] = { ...kept, delta: kept.delta + at.delta, ratio: Math.min(Math.abs(kept.delta + at.delta) / threshold, 5), accumulated: true };
          merged = true;
          break;
        }
      }
      if (merged) continue;
      if (active.length >= 100) active.shift(); // `KL:441-444`: the oldest goes before the 101st is drawn
    }
    active.push(bubbles.length);
    bubbles.push({ t: chart[index]![0], price: at.price, delta: at.delta, side: at.side, ratio: Math.min(Math.abs(at.delta) / threshold, 5), session });
  }
  // The two of `KENJI:955-959` that act on the list, not on the drawing. Mitigation first (`KL:331`, `:351`): a bullish bubble dies when a
  // later bar closes under its level, a bearish one when it closes over it, and with `bigTrades_mitigated` false — the Pine's default — it is
  // **deleted** (`KL:339-346`); true keeps it, greyed. The `last` cap comes after, per side and only in `Present` (`KL:295-314`).
  const showMitigated = retention.mitigated === true;
  const kept: BookmapBar[] = [];
  for (const bubble of bubbles) {
    let crossed = false;
    for (const bar of chart) {
      if (bar[0] <= bubble.t || bar[0] + barMs > now) continue; // only bars after the one that created it
      if (bubble.side === 'bull' ? bar[4] < bubble.price : bar[4] > bubble.price) { crossed = true; break; }
    }
    if (crossed && !showMitigated) continue;
    kept.push(crossed ? { ...bubble, mitigated: true } : bubble);
  }
  if ((retention.mode ?? 'Present') === 'Historic') return kept;
  const size = Math.max(1, Math.min(200, Math.round(retention.last ?? 50)));
  const cap = (side: 'bull' | 'bear'): BookmapBar[] => {
    const list = kept.filter(item => item.side === side);
    return list.length <= size ? list : list.slice(list.length - size);
  };
  return [...cap('bull'), ...cap('bear')].sort((a, b) => a.t - b.t);
}

export const BOOKMAP_TRIGGER: StudyDef = {
  api: STUDY_API,
  id: 'bookmap-trigger',
  name: 'Bookmap',
  inputs: INPUTS,
  data: [
    // `ta.sma(volume, 500)` and the 500-bar percentile (`KL:392-442`) are `na` before five hundred bars, so the series needs them before the first
    // bar it draws (T-1232). The host serves the warm-up; the painter draws only the view.
    { key: 'chart', kind: 'candles', label: 'Chart candles', warmup: LOOKBACK },
    { key: 'ltf', kind: 'candles', label: 'Lower-timeframe candles' },
  ],
  compute(ctx): StudyOutput | null {
    // Why the piece can be on and draw nothing (T-1231): its threshold is the 500-bar percentile the Pine reads (`KL:392-442`), so before the
    // series holds that warm-up every bar is skipped and the answer is empty with no error. The panel says it with the number instead.
    const chartOnly = ctx.data.candles('chart');
    // The lower bars are asked for **the stretch the chart itself covers**, not for `LOOKBACK` chart bars of them (T-1229): the bubbles only read
    // the bars that fall inside the chart bars handed in, and asking 500 of them in minutes went past what the loader can reach (twelve pages of
    // fifteen hundred minute bars), so the piece was on and drew nothing. The Pine asks for no more either: `request.security_lower_tf` hands the
    // lower bars inside each chart bar.
    const chart = chartOnly;
    const backMs = chart && chart.bars.length > 1 ? Math.max(0, ctx.now - chart.bars[0]![0]) : undefined;
    const ltf = ctx.data.candles('ltf', backMs);
    if (!chart || !ltf) return null; // the host does not resolve `ltf` yet: nothing is drawn, never a series in its place
    // `ta.sma(volume, 500)` and the 500-bar percentile are `na` until that many bars exist, so nothing can fire before the five hundredth: the panel
    // gets the count and what is missing instead of a silent `null` (`KL:392-442`, the same gate as `ready` below).
    if (chart.bars.length < LOOKBACK) {
      return {
        plots: [],
        readout: [{ id: 'bm:warmup', label: 'warm-up', values: [{ id: 'bars', value: chart.bars.length }, { id: 'needed', value: LOOKBACK }, { id: 'missing', value: LOOKBACK - chart.bars.length }] }],
      } as StudyOutput;
    }
    const params = readInputs(INPUTS, ctx.params);
    // The windows are the Pine's zone (D-14, D-30): the page's zone never moves them, only writes their hours.
    const zone: CycleZone = CYCLE_90_ZONE;
    // The bins are cut over the higher-timeframe candle the Pine names (`OEC:2761`); `chart` is its own default (`OEC:159`) and the shape
    // the input offers instead of Pine's empty string. A series the host cannot answer falls back to the chart bar, said in the card.
    const tf = text(params, 'tf', 'chart');
    // `bigTradesRange` (`KL:935`): `Bar` cuts the bins over the chart bar itself; `HTF` over the **previous** `TF_candle_1` candle, whose
    // high and low the Pine carries as `lastHigh_actual`/`lastLow_actual`. The series is the automatic higher frame of the chart when the host
    // answers it; when it does not, the chart bar stands in and the card says so (T-1190).
    const htf = text(params, 'range', 'Bar') === 'HTF'
      ? ctx.data.candles(`series:${autoTimeframe(chartBar(chart.bars), 'htf-pda')}`, 4 * timeframeMs(autoTimeframe(chartBar(chart.bars), 'htf-pda')))
      : (tf === 'chart' ? null : ctx.data.candles(`series:${tf}`));
    const bubbles = bookmapBars(chart.bars, ltf.bars, ctx.now, zone, {
      bins: Math.round(number(params, 'bins', 10)),
      mode: text(params, 'mode', 'auto'),
      autoTop: number(params, 'autoTop', 10),
      manual: number(params, 'manual', 1_000),
      minVolPct: number(params, 'minVolPct', 80),
    }, htf ? htf.bars : null, ctx.tickSize ?? null, {
      mitigated: params['mitigated'] === true,
      mode: text(params, 'retention', 'Present') === 'Historic' ? 'Historic' : 'Present',
      last: Math.round(number(params, 'last', 50)),
    });
    // An empty answer with the series at the warm-up line is the case the person met: exactly five hundred bars, so the percentile is all zeros and
    // the threshold is 0 — the piece is on and cannot draw. It says it with the numbers rather than returning a silent `null` (T-1231).
    if (!bubbles.length) {
      if (chart.bars.length <= LOOKBACK) {
        return {
          plots: [],
          readout: [{ id: 'bm:warmup', label: 'warm-up', values: [{ id: 'bars', value: chart.bars.length }, { id: 'needed', value: LOOKBACK + 500 }, { id: 'missing', value: LOOKBACK + 500 - chart.bars.length }] }],
        } as StudyOutput;
      }
      return null;
    }
    const plots: Plot[] = [], tags = [];
    // `bigTradesBuyColor`/`_SellColor` (`:941-942`), the palette's while they are untouched. The two trigger colours (`:943-944`) are carried
    // with their own `active` but not drawn: this piece has no trigger of its own to colour, and inventing one would be worse than saying it
    // (T-1190).
    const chosen = (id: string, fallback: string): string => {
      const value = params[id], fallbackOf = INPUTS.find(input => input.id === id)?.default;
      return typeof value === 'string' && value !== fallbackOf ? value : fallback;
    };
    const bullInk = chosen('bullColor', ctx.palette.bid), bearInk = chosen('bearColor', ctx.palette.ask);
    // `bigTradesLabelStyle` (`:936`): a bubble or a plain label; `bigTradesShowValue` (`:937`) puts the delta in the text instead of the size.
    const asLabel = text(params, 'labelStyle', 'Bubbles') === 'Label', showValue = params['showValue'] === true;
    // Where the bubbles are placed, `bigTradesStyle` and `bigTrades_anchor` (`KENJI:906`, `:908`): the moment the bubble was found, or `Anchor`
    // bars past the last one for the right-anchored look. The volume-anchored one and `Dynamic` need the Pine's own placement rule (`KL:456-503`),
    // which is read next; until then they draw as the moment-anchored one and that is said in `Notas:` rather than guessed.
    const placement = text(params, 'style', 'Moment Anchored');
    const anchorBars = Math.max(0, Math.round(number(params, 'anchor', 90)));
    const chartMs = chart.bars.length > 1 ? chart.bars[1]![0] - chart.bars[0]![0] : 60_000;
    // `dynamic_state`: `1` when the last mitigation was bullish, `-1` when bearish (`Kenji-library:513-519`). Only that side is taken to `+anchor`.
    const lastMitigated = [...bubbles].reverse().find(bubble => bubble.mitigated === true);
    const dynamicSide: 'bull' | 'bear' | null = lastMitigated ? lastMitigated.side : null;
    const windowStart = chart.bars[0]?.[0] ?? 0;
    // The view's right edge is where a placement in the future has to land (`ctx.view.t1`), as the key levels' `Right` closes at the plot's edge.
    const limit = Number.isFinite(ctx.view.t1) ? ctx.view.t1 : Infinity;
    const placedAt = (t: number, side: 'bull' | 'bear'): number => bubbleTime(t, placement, anchorBars, ctx.now, chartMs, side, dynamicSide, windowStart, limit);
    const triggerInk = (side: 'bull' | 'bear'): string => side === 'bull' ? text(params, 'bullTriggerColor', '#ffff00') : text(params, 'bearTriggerColor', '#ff00ff');
    for (const bubble of bubbles) {
      // A mitigated bubble the switch keeps is greyed, as the Pine does (`KL:341-343`): its level is gone. An accumulation takes the trigger
      // colour (`Kenji-library:435-448`: `color_iceberg`), and its text carries the Pine's `'◄ '` marker.
      const color = bubbleInk(bubble, { bull: bullInk, bear: bearInk, bullTrigger: triggerInk('bull'), bearTrigger: triggerInk('bear') });
      const textOf = showValue ? String(Math.round(bubble.delta)) : labelOf(bubble.session.id);
      const marked = bubble.accumulated ? `◄ ${textOf}` : textOf;
      if (asLabel) plots.push({ kind: 'label', t: placedAt(bubble.t, bubble.side), p: bubble.price, text: marked, color });
      else plots.push({ kind: 'mark', t: placedAt(bubble.t, bubble.side), p: bubble.price, color, shape: 'dot', ...(bubble.accumulated || showValue ? { text: marked } : {}) });
      tags.push({ key: `bm:${bubble.side}:${bubble.session.id}`, price: bubble.price, text: `${bubble.side === 'bull' ? '+BM' : '-BM'} ${labelOf(bubble.session.id)}`, rank: 3.5, color });
    }
    // What other pieces read (T-1237): the bubbles this piece drew, one row each, with the side and the cycle session they belong to — ST entry's
    // trigger is `side:session` (`OEC:3020`/`:3031`), so those two travel with the price and the bar. The list is the one already cut by `Last` and
    // `Mitigation`, so a piece reading it sees exactly the bubbles on the chart, never a second calculation with its own copy of the settings.
    const readout = bubbles.map(bubble => ({
      id: 'bm:bubbles',
      label: bubble.side,
      values: [
        { id: 'side', value: bubble.side },
        { id: 'session', value: bubble.session.id },
        { id: 'price', value: bubble.price },
        { id: 't', value: bubble.t },
      ],
    }));
    return { plots, tags, readout };
  },
};
