import { STUDY_API, type Plot, type ReadoutRow, type ReadoutValue, type StudyCandles, type StudyDef, type StudyOutput } from '../engine/studies/contract.ts';
import { readInputs, type InputSpec } from '../engine/inputs/schema.ts';
import { timeframeMs, type Timeframe } from '../engine/time/timeframe.ts';
import type { Bar } from '../engine/series/source.ts';

/**
 * `trend-bias`: the OEC TREND CONTINUATION table (`OddEyeCircle` 107-151 inputs, `:2181-2260` table), the piece the platform plan calls
 * `orderflow-bias`. It is a bias by candles, not orderflow: `Orderflow_Bias_TF` (`:834-900`) only compares closes against the previous
 * candle's high and low, which is why D-21 names it the candle bias and A-10 leaves the real delta as a later, separate improvement.
 *
 * One row a timeframe of the group its chart timeframe shows (`GlobalFunctions library:190-200`): M, D, 1H, 5m on a 5m/1H/D/M chart; W,
 * 4H, 15m on a 1m/15m/4H/W chart; none on 30m, as Pine draws no column there. The formula is Pine's, in its order: green (`close >=
 * high[2]`), red (`close <= low[2]`), then grey/neutral inside `[low[2], high[2]]` (equal bounds included, overriding green/red), then the
 * previous candle's colours (`prev_*`) overriding that.
 *
 * The engine's contract has no pane-anchored table, so it is drawn with `label`s and 0.5 px rules placed from `ctx.view`: same columns, states
 * and counts as Pine, anchored to the chart instead of the pane, in the grammar of A (no cell is a box: the side is a 2 px rule at the foot).
 *
 * `compute` is pure: no hub, store, DOM or canvas; the seven series come resolved through `StudyData.candles`.
 */
const MINUTE = 60_000, DAY = 86_400_000, WEEK = 604_800_000, MONTH = 2_592_000_000;

export type BiasState = 'bullish' | 'bearish' | 'pre-bullish' | 'pre-bearish' | 'neutral';

const TF_LABEL: Readonly<Record<Timeframe, string>> = { '1': '1m', '5': '5m', '15': '15m', '30': '30m', '60': '1H', '240': '4H', D: 'D', W: 'W', M: 'M' };
const STATE_TEXT: Readonly<Record<BiasState, string>> = { bullish: 'Bullish', bearish: 'Bearish', 'pre-bullish': 'Pre-Bullish', 'pre-bearish': 'Pre-Bearish', neutral: 'Neutral' };

/** The seven series Pine reads through `request.security` (`:131-151`): one `DataReq` each, resolved by the host. */
const SERIES: readonly { readonly tf: Timeframe; readonly key: string; readonly label: string }[] = [
  { tf: 'M', key: 'series:M', label: 'Monthly candles' },
  { tf: 'W', key: 'series:W', label: 'Weekly candles' },
  { tf: 'D', key: 'series:D', label: 'Daily candles' },
  { tf: '240', key: 'series:240', label: '4-hour candles' },
  { tf: '60', key: 'series:60', label: '1-hour candles' },
  { tf: '15', key: 'series:15', label: '15-minute candles' },
  { tf: '5', key: 'series:5', label: '5-minute candles' },
];

/**
 * The ten of the Pine's `group_TREND` (`OddEyeCircle:84-94`), plus none of ours: `Display` (`trend_orientation`), `Size` (`trend_text`),
 * `Position` (`trend_position`), `Text` (`trend_text_css`), the three cell colours (`trend_biasup_close_css`, `trend_biasneutral_close_css`,
 * `trend_biasdn_close_css`), `Countdown` (`trend_counter`), `Orderflow` (`trend_orderflow`) and `Actual` (`trend_orderflow_actual`).
 *
 * The Pine dims nine of them on `show_tf_orderflow` (`:34`), the switch that turns the whole HTF orderflow block off. The product's piece has
 * one switch of its own and the lamp for the piece, so the nearest one is `Orderflow`: with it off the table draws bodies, not sides, and its
 * settings have nothing to say (T-1177, and the difference is in `Notas`).
 */
const INPUTS: readonly InputSpec[] = [
  { id: 'orderflow', kind: 'bool', name: 'Orderflow', default: true, group: 'Trend continuation' },
  // `trend_orderflow_actual` (`OddEyeCircle:98`): **one** switch, and it draws both `Actual` cells. The two frames are the Pine's own
  // (`GlobalFunctions library:304` and `:340`), never a pair the person picks: the three "marco de la actual" inputs this piece used to
  // have were our invention, and they are gone (T-1140).
  { id: 'actual', kind: 'bool', name: 'Actual', default: true, group: 'Trend continuation', active: values => values['orderflow'] !== false, inactive: 'Needs Orderflow on.' },
  // The Pine's four colours (`:88-91`) went with the table (T-1300): the work bar paints the cells with the page's own tones, so a colour
  // input here would be a control that changes nothing.
];

/** The bar size of a series, from its own starts (a study is told bars, not the chart's timeframe name). */
function barSize(bars: readonly Bar[]): number {
  for (let index = 1; index < bars.length; index += 1) { const step = bars[index]![0] - bars[index - 1]![0]; if (step > 0) return step; }
  return MINUTE;
}

/**
 * The bias of a series from its last two closed candles, as `Orderflow_Bias_TF` (`:834-900`): the last closed bar is Pine's `close[1]` /
 * `high[1]` / `low[1]`, the one before its `[2]`. `null` until there are three bars (two closed ones).
 */
export function biasState(bars: readonly Bar[], closed = bars.length - 2): BiasState | null {
  if (closed < 1 || bars.length < closed + 1) return null;
  const a = bars[closed]!, b = bars[closed - 1]!;
  const high1 = a[2], low1 = a[3], close1 = a[4], high2 = b[2], low2 = b[3], close2 = b[4];
  let state: BiasState = 'neutral';
  // Pine's order, exactly: green, red, then grey/neutral (equal bounds count, and it overrides the two above), then the previous candle's.
  if (close1 >= high2) state = 'bullish';
  else if (close1 <= low2) state = 'bearish';
  if (close1 <= high2 && close1 >= low2) state = 'neutral';
  const prevGreen = (low1 < low2 && close1 <= high2 && close1 >= low2 && close1 > close2) || (high1 > high2 && low1 < low2 && close1 > close2);
  const prevRed = (high1 > high2 && close1 <= high2 && close1 >= low2 && close1 < close2) || (high1 > high2 && low1 < low2 && close1 < close2);
  if (prevGreen) state = 'pre-bullish';
  else if (prevRed) state = 'pre-bearish';
  // Not even a previous-candle colour: Pine leaves its default white, which the table shows as the neutral background.
  return state;
}

/** `Orderflow_Actual_TF` (`OddEyeCircle:776-800`): the bias of the candle that is **still forming**, against the closed one before it. */
export function actualBias(cur: Bar, prev: Bar): BiasState {
  const close = cur[4], high = cur[2], low = cur[3];
  const prevHigh = prev[2], prevLow = prev[3], prevClose = prev[4];
  const green = close >= prevHigh;
  const red = close <= prevLow;
  const neutral = close <= prevHigh && close >= prevLow;
  // Pine's `and` binds tighter than `or`: each side of the `or` is one run of `and`s.
  const prevGreen = (low < prevLow && neutral && close > prevClose) || (high > prevHigh && low < prevLow && close > prevClose);
  const prevRed = (high > prevHigh && neutral && close < prevClose) || (high > prevHigh && low < prevLow && close < prevClose);
  let state: BiasState = 'neutral'; // Pine's default is `color.white`, which the table shows as grey
  if (green) state = 'bullish'; else if (red) state = 'bearish';
  if (neutral) state = 'neutral';
  if (prevGreen) state = 'pre-bullish'; else if (prevRed) state = 'pre-bearish';
  return state;
}

/**
 * The live column: the bias of the series' **forming** candle, or `null` when its last bar has already closed (the exchange had not
 * opened the next one yet). The forming bar is the one whose period still contains `now`; if it has ended, nothing of this series is
 * under way and the column is not drawn.
 */
export function liveBias(bars: readonly Bar[], now: number, tf?: Timeframe): BiasState | null {
  if (bars.length < 2) return null;
  const size = tf ? timeframeMs(tf) : barSize(bars);
  const cur = bars[bars.length - 1]!;
  // The last bar is the one under way only when its own period has not ended (`start + tf > now`). A series that ends in a **closed** bar has
  // no candle forming, and the cell then says the last closed one instead of nothing: the Pine's `request.security` always hands it the bar
  // under way, so this is the case where our series is one bar short — a word one bar old reads better than an empty cell (T-1180).
  if (!(cur[0] + size > now)) return biasState(bars, bars.length - 1);
  return actualBias(cur, bars[bars.length - 2]!);
}

/** The fallback when `orderflow` is off: Pine colours the cell by the candle's own body (`close > open`). */
export function candleDirection(bars: readonly Bar[]): BiasState | null {
  if (bars.length < 2) return null;
  const bar = bars[bars.length - 2]!;
  return bar[4] > bar[1] ? 'bullish' : bar[4] < bar[1] ? 'bearish' : 'neutral';
}

/** Which group of columns a chart timeframe shows (`show_M` / `show_W`, `GlobalFunctions library:190-200`). */
export function biasGroups(chartMs: number): { month: boolean; week: boolean } {
  const minutes = Math.round(chartMs / MINUTE);
  if (chartMs < DAY) return { month: minutes === 5 || minutes === 60, week: minutes === 1 || minutes === 15 || minutes === 240 };
  if (chartMs === WEEK) return { month: false, week: true };
  return { month: chartMs >= DAY, week: false };
}

/**
 * The timeframes the table shows, **fine to coarse** as the Pine lays them out (T-1084): `5, 60, D, M` on a 1h chart and `15, 240, W` on a
 * 4h one (`OddEyeCircle:2199-2211`, cells 1 to 4; read left to right the fine frame comes first). Before T-1084 this listed the same four
 * the other way round, which is what the person saw as "the order is reversed".
 */
export function biasTimeframes(chartMs: number): readonly Timeframe[] {
  const groups = biasGroups(chartMs);
  if (groups.month) return ['5', '60', 'D', 'M'];
  if (groups.week) return ['15', '240', 'W'];
  return [];
}

/**
 * The two frames the `Actual` cells speak for, as the Pine's own functions choose them (`GlobalFunctions library:304` `auto_htfPDA` and `:340`
 * `auto_htfPDA_candle_2`), from the chart's bar size: a 1h chart reads `D` and `M`, a 4h one `W` and `M`. Pine's `12M` has no series in
 * this page, so it is read as `M`: on a daily (or coarser) chart both cells name `M`, which is a loss declared in `Notas`, never a guess.
 */
export function actualFrames(chartMs: number): readonly [Timeframe, Timeframe] {
  const minutes = Math.round(chartMs / MINUTE);
  if (chartMs < DAY) {
    const first: Timeframe = minutes < 5 ? '15' : minutes < 15 ? '60' : minutes < 60 ? '240' : minutes < 240 ? 'D' : 'W';
    const second: Timeframe = minutes < 5 ? '240' : minutes < 15 ? 'D' : minutes < 60 ? 'W' : 'M';
    return [first, second];
  }
  return ['M', 'M'];
}

/** The next close of `tf` after `now`: the UTC period boundary, as the exchange stamps them (00:00, Monday, the 1st). */
export function nextClose(now: number, tf: Timeframe): number {
  if (tf === 'M') { const date = new Date(now); return Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 1); }
  if (tf === 'W') { const day = Math.floor(now / DAY) * DAY, weekday = new Date(day).getUTCDay(); return day - ((weekday + 6) % 7) * DAY + WEEK; }
  const size = timeframeMs(tf);
  return Math.floor(now / size) * size + size;
}

/**
 * Pine's `_Counter` text (`GlobalFunctions library:1641`) as the table composes it, which is **not** the same units for every frame
 * (`OddEyeCircle:2224-2238`): the monthly and weekly cells print days and hours only, the daily and 4-hour ones hours, minutes and seconds, and
 * the 1-hour, 15- and 5-minute ones minutes and seconds. A unit at zero is left out, and a cell whose units are all zero is empty — Pine's
 * concatenation of `(d > 0 ? d + 'D ' : '') + …` leaves it so. Without a frame (a caller asking for the whole counter) every unit is shown and
 * an empty count reads `0s`.
 */
export function countdownText(now: number, close: number, tf?: Timeframe): string {
  const total = Math.max(0, Math.floor((close - now) / 1000));
  const d = Math.floor(total / 86_400), h = Math.floor(total % 86_400 / 3_600), m = Math.floor(total % 3_600 / 60), s = total % 60;
  const coarse = tf === undefined ? ['D', 'H', 'm', 's'] : tf === 'M' || tf === 'W' ? ['D', 'H'] : tf === 'D' || tf === '240' ? ['H', 'm', 's'] : ['m', 's'];
  const parts = coarse.filter(unit => (unit === 'D' ? d : unit === 'H' ? h : unit === 'm' ? m : s) > 0)
    .map(unit => unit === 'D' ? `${d}D` : unit === 'H' ? `${h}H` : unit === 'm' ? `${m}m` : `${s}s`);
  if (parts.length) return parts.join(' ');
  return tf === undefined ? '0s' : '';
}


/** The chart's own frame, as the table names it: the first cell of the `Actual` group (`OddEyeCircle:541`). */
export function chartFrame(chartMs: number): Timeframe {
  if (chartMs >= MONTH) return 'M';
  if (chartMs >= WEEK) return 'W';
  if (chartMs >= DAY) return 'D';
  const minutes = Math.round(chartMs / MINUTE);
  return minutes >= 240 ? '240' : minutes >= 60 ? '60' : minutes >= 15 ? '15' : '5';
}

export const TREND_BIAS: StudyDef = {
  api: STUDY_API,
  id: 'trend-bias',
  name: 'Trend bias',
  inputs: INPUTS,
  data: [{ key: 'chart', kind: 'candles', label: 'Chart candles' }, ...SERIES.map(s => ({ key: s.key, kind: 'candles' as const, label: s.label }))],
  compute(ctx): StudyOutput | null {
    const params = readInputs(INPUTS, ctx.params);
    const orderflow = params['orderflow'] !== false;
    const actual = params['actual'] !== false;
    const chart = ctx.data.candles('chart');
    const chartMs = chart ? barSize(chart.bars) : 0;
    // The last **closed** bar by the data, not by the index (T-1180): a series whose last bar is still forming ends one bar later than one
    // that already closed, and reading `length - 2` blindly showed the previous candle's colour — one step behind, "a veces falla".
    const lastClosed = (bars: readonly Bar[], tf: Timeframe): number => {
      const last = bars[bars.length - 1];
      return last && last[0] + timeframeMs(tf) > ctx.now ? bars.length - 2 : bars.length - 1;
    };
    const stateOf = (bars: readonly Bar[], tf: Timeframe): BiasState | null => orderflow ? biasState(bars, lastClosed(bars, tf)) : candleDirection(bars);
    // A frame's own series, asked with the stretch it needs: the loader's default is the two periods before the view, and a frame that ends
    // before it reached that much never carried the bar under way (T-1180, the same ask as tile T-1173 did for the HTF candles).
    const seriesOf = (tf: Timeframe): StudyCandles | null => {
      const def = SERIES.find(s => s.tf === tf);
      return def ? ctx.data.candles(def.key, 6 * timeframeMs(tf)) : null;
    };
    if (!biasTimeframes(chartMs).length && !actual) return null;
    // The table's data, as codes and numbers for the panel (T-1071, D-31): one row a frame of the family the chart shows, the same
    // `biasTimeframes` the cells above use, so the painted table and a panel cannot disagree. `bias` is the state of the last **closed**
    // candle — the one the cell's colour is read from — and `prevState` the one before it; `close`/`prevClose` are their closes, the two
    // numbers the bias compares, and `msToClose` is Pine's `_Counter` to the close of the candle under way (`:2214-2230`).
    const readout: ReadoutRow[] = [];
    for (const tf of biasTimeframes(chartMs)) {
      const def = SERIES.find(s => s.tf === tf);
      const series = seriesOf(tf);
      // A frame is always a row (T-1095): the history that answers 5m, D and M arrives after the first frames, and dropping the row until
      // it did left a table with one line. With no series the row still says which frame it is and when it closes, and carries no state —
      // a gap the panel paints as one, never a zero or a made-up side.
      const values: ReadoutValue[] = [
        { id: 'tf', value: TF_LABEL[tf] },
        { id: 'msToClose', value: Math.max(0, nextClose(ctx.now, tf) - ctx.now) },
      ];
      if (series && series.bars.length >= 3) {
        const bars = series.bars, closed = bars[bars.length - 2]!, before = bars[bars.length - 3]!;
        const state = stateOf(bars, tf);
        if (state) {
          values.push({ id: 'bias', value: state }, { id: 'close', value: closed[4] }, { id: 'prevClose', value: before[4] });
          const previous = stateOf(bars.slice(0, -1), tf);
          if (previous) values.push({ id: 'prevState', value: previous });
          // Pine's `Actual` cell (`Orderflow_Actual_TF`, `:776-800`): the candle still forming, when its series has one.
          const forming = liveBias(bars, ctx.now);
          if (forming) values.push({ id: 'actual', value: forming });
        }
      }
      readout.push({ id: `bias:${tf}`, label: TF_LABEL[tf], values });
    }
    // The same two cells as rows for a panel (T-1071, D-31): the frame's name and its countdown always, its forming candle's state when that
    // series has arrived — a cell with no series is a gap, never a missing row (T-1095, T-1140).
    const actualTfs: readonly Timeframe[] = actual ? [...actualFrames(chartMs)] : [];
    for (let index = 0; index < actualTfs.length; index += 1) {
      const tf = actualTfs[index]!;
      const def = SERIES.find(s => s.tf === tf);
      const series = seriesOf(tf);
      const state = series ? liveBias(series.bars, ctx.now, tf) : null;
      const values: ReadoutValue[] = [
        { id: 'tf', value: TF_LABEL[tf] },
        { id: 'msToClose', value: Math.max(0, nextClose(ctx.now, tf) - ctx.now) },
      ];
      if (state) values.push({ id: 'bias', value: state });
      readout.push({ id: `actual:${index + 1}`, label: `Actual ${TF_LABEL[tf]}`, values });
    }
    // T-1300 (Chief, 2026-11-26): the table is **no longer painted on the chart**. It lives in the work bar of the bottom row
    // (`app/workbar.ts`), which reads this readout and paints its own cells; the piece keeps computing and publishing the same numbers, so
    // the deck's lamp still switches it and nothing is worked out twice. What went with the table: the `Position`, `Display` and `Size`
    // inputs (they only dressed it) and about a hundred lines of text measuring per frame.
    return { plots: [], readout };
  },
};
