import { dayWindows, monthWindows, offsetMs, weekWindows, type ProfileWindow } from '../traded/sessions.ts';
import type { CandleRow } from '../store.ts';
import { aggregate, periodStart } from '../../indicators/htf-candles.ts';
import type { Bar } from '../../engine/series/source.ts';
import type { Timeframe } from '../../engine/time/timeframe.ts';
import { biasState } from '../../indicators/trend-bias.ts';
import { showsPeriod } from '../../indicators/previous-ohlc.ts';

/**
 * Key levels from each market's own daily, weekly and monthly candles (the exchange's 1d / 1w / 1M opens and
 * closes read **in UTC whatever the venue** — midnight, Monday, the 1st — not a wall-clock zone calendar and not the exchange's own 1d
 * candle: OKX's 1d bars begin at 16:00 UTC, so folding these from its days would put `PDC` on another day than the chart's HTF candle
 * (T-1079). They come from hourly bars folded with `periodStart`, the same function `htf-candles` uses). Previous high,
 * low and close of each completed period are drawn across the next one; an untouched level can run on until price
 * reaches it.
 */

export type PeriodKind = 'day' | 'week' | 'month';
export const PERIOD_KINDS: readonly PeriodKind[] = ['day', 'week', 'month'];
/** Which lines of one kind of period are drawn: the previous one's high and low, and its close. */
/**
 * One period row of the panel, each control its own (T-1202/T-1203): `on` switches the row without touching its three boxes, so turning a row
 * off and back on returns it as it was, and `high`, `low` and `close` are the Pine's per-timeframe boxes (`OEC:2085-2144`).
 */
export interface PeriodLines { on: boolean; high: boolean; low: boolean; close: boolean }
export type LevelWhat = 'high' | 'low' | 'close';

const MINUTE = 60_000, HOUR = 3_600_000, DAY = 86_400_000;
/** A period's row id in the block, which is what `showsPeriod` reads. */
const PERIOD_FRAME: Readonly<Record<PeriodKind, string>> = { day: 'pd', week: 'pw', month: 'pm' };
/** How far back the levels reach: about two months of daily bars cover previous week and month. */
export const MAX_BACK_MS = 62 * DAY;

/**
 * How far back one bar size's loader keeps its bars: at least the levels' two months, and at least `bars` bars of this size. A monthly series
 * asked for ten candles cannot be kept by a span of two months — it kept two (October and November, T-1282, measured on the published page:
 * `Marco 2M · 2 velas` with `source: series` and no amber), so the piece read a short series as if that were all the exchange had.
 */
export function keepBackMs(barMs: number, bars = MAX_PREVIOUS): number {
  const span = Math.max(1, Math.round(barMs)) * Math.max(1, Math.round(bars));
  return Math.max(MAX_BACK_MS, span);
}
/** Look back this many completed periods when scanning for untouched levels still in view. */
const LOOKBACK: Readonly<Record<PeriodKind, number>> = { day: 12, week: 8, month: 3 };
/**
 * The most previous periods one kind may show: the Pine's own top, twenty (`keylevels_last`, `maxval = 20`, `:85`; `_cap`, `:943`). Each one
 * drawn needs the one before it, so a little more is read — `MAX_REACH_MS` below is the span that covers that.
 */
export const MAX_PREVIOUS = 20;
const MAX_LINES = 600;

/** Exchange kline length used when asking for this period's native candles. */
export const PERIOD_MS: Readonly<Record<PeriodKind, number>> = {
  day: DAY,
  week: 604_800_000,
  month: 2_592_000_000,
};
/**
 * How far back the deepest kind can reach: the levels' two months plus a month, or twenty-two periods of the month (the twenty `_cap` allows,
 * the one under way and the one before the oldest drawn). It is the floor `neededFrom` clamps to, and the span the native period candles are kept
 * for (`hub.ts`), so a request for twenty months is not cut to three (T-1298).
 */
export const MAX_REACH_MS = Math.max(MAX_BACK_MS + PERIOD_MS.month, PERIOD_MS.month * (MAX_PREVIOUS + 2));

/** One period bar as the exchange sent it (open time = exchange boundary). */
export interface PeriodBar {
  openTime: number;
  /** Exclusive end when known (next bar's open, or derived for the bar under way). */
  closeTime: number;
  open: number;
  high: number;
  low: number;
  close: number;
  /** True when the exchange has closed this bar (a later bar exists, or heldTo is past closeTime). */
  complete: boolean;
}

export type PeriodBars = Readonly<Record<PeriodKind, readonly PeriodBar[]>>;

/** One line on the chart. */
export interface KeyLine {
  period: PeriodKind;
  what: LevelWhat;
  /** A previous period's level (drawn over the next one). */
  prev: boolean;
  price: number;
  from: number;
  to: number;
  /**
   * For a previous period's level not traded through by `to`: the first later bar that reached it, or null if none
   * yet (runs on to the right edge). Absent: not extended.
   */
  reached?: number | null;
  /** When the period whose level it is began. */
  of: number;
  /**
   * The side the level's period closed on (`prev.close` against its open), which is what its line and label are painted with (T-1087): the
   * same direction `trend-bias` and the HTF candles use, so the three cannot disagree about which side a close fell on.
   */
  bias?: 'bull' | 'bear' | 'neutral';
  /** The first bar that traded through the level, or null while price has not reached it (T-1222). */
  touched?: number | null;
  /** The newest completed period's close: the one that is never dimmed (T-1222). */
  newest?: boolean;
  window: string;
}

/**
 * Build period bars from native exchange candles of one size. `closeTime` of each bar is the next bar's open; the
 * last bar's end is `lastEnd` (now, or the derived period end). A bar is complete when a later bar exists or
 * `heldTo` is at least its close (with a small slack for refresh lag).
 */
export function periodBarsFromCandles(candles: readonly CandleRow[], lastEnd: number, heldTo: number = Infinity, slackMs = 6 * 60_000): PeriodBar[] {
  if (!candles.length) return [];
  const sorted = [...candles].sort((a, b) => a[0] - b[0]);
  const out: PeriodBar[] = [];
  for (let i = 0; i < sorted.length; i++) {
    const c = sorted[i]!;
    const closeTime = i + 1 < sorted.length ? sorted[i + 1]![0] : lastEnd;
    if (!(closeTime > c[0])) continue;
    const complete = i + 1 < sorted.length || heldTo >= closeTime - slackMs;
    out.push({ openTime: c[0], closeTime, open: c[1], high: c[2], low: c[3], close: c[4], complete });
  }
  return out;
}

/** First bar at or after `after` whose range reaches `price`. */
/**
 * The period bars of one kind, folded from **hourly** bars with `periodStart` and `aggregate` — the same pair `htf-candles` uses to fold the
 * chart's series (T-1079). That is what makes `PDH`/`PDL`/`PDC` the levels of the candle the chart draws, whatever the exchange stamps its
 * own 1d bars at: OKX begins its days at 16:00 UTC, so its `1d` close belongs to another day than the chart's. A kind whose hours do not
 * reach back to the start of the previous period yields nothing — half a period is not a period — and the caller says so instead of mixing.
 */
export function periodBarsFromHourly(hours: readonly CandleRow[], kind: PeriodKind, now: number): PeriodBar[] {
  if (!hours.length) return [];
  const tf: Timeframe = kind === 'day' ? 'D' : kind === 'week' ? 'W' : 'M';
  const folded = aggregate(hours.map(bar => bar as unknown as Bar), tf);
  const out: PeriodBar[] = [];
  // A period the hours only reach part way into is not built: its open, high or low would come from the middle of it.
  const first = folded.length && hours[0]![0] > folded[0]!.start ? 1 : 0;
  for (let index = first; index < folded.length; index += 1) {
    const bar = folded[index]!, next = folded[index + 1];
    // The period's own length, taken from the next one's start: a month is 28 to 31 days and never a constant.
    const closeTime = next ? next.start : periodStart(now + 1, tf) + (folded.length > 1 ? folded[folded.length - 1]!.start - folded[folded.length - 2]!.start : 0);
    if (!(closeTime > bar.start)) continue;
    out.push({ openTime: bar.start, closeTime, open: bar.open, high: bar.high, low: bar.low, close: bar.close, complete: closeTime <= now });
  }
  return out;
}

/**
 * The first **chart** bar at or after `after` that traded through `price`. This is the Pine's touch: it walks every bar of the chart and keeps that
 * bar's own time (`OddEyeCircle:1377-1390`, `array.set(_po_touch, _jj, time)`), and the line ends at `_tch`, that time (`:1423`). Walking the
 * day/week/month bars instead snapped the touch to the start of the period, which cut a low touched mid-morning back at the period's edge (T-1226).
 */
export function touchedOnChart(bars: readonly Bar[], price: number, after: number): number | null {
  for (const b of bars) {
    if (b[0]! < after) continue;
    if (b[3]! <= price && price <= b[2]!) return b[0]!;
  }
  return null;
}

export function reachedAtBar(price: number, after: number, bars: readonly PeriodBar[]): number | null {
  for (const b of bars) {
    if (b.openTime < after) continue;
    if (b.low <= price && price <= b.high) return b.openTime;
  }
  return null;
}

/** Earliest candle time needed for the enabled lines. */
export function neededFrom(lines: Readonly<Record<PeriodKind, PeriodLines>>, _zone: string, t0: number, now: number, count = 1): number {
  let from = now;
  for (const period of PERIOD_KINDS) {
    const want = lines[period];
    // The row's own switch, then its three boxes: a row that is off draws nothing and keeps what its boxes said (T-1203).
    if (!want.on || (!want.high && !want.low && !want.close)) continue;
    const periods = Math.max(LOOKBACK[period], Math.min(MAX_PREVIOUS, count) + 2);
    const span = PERIOD_MS[period] * periods;
    from = Math.min(from, Math.min(t0, now) - span);
  }
  // Never earlier than the deepest kind can be drawn: twenty-two months when twenty periods are asked (T-1298). The two-month floor alone cut a
  // request for twenty weeks or twenty months to three, so the panel offered periods the loader was never asked for.
  return Math.max(from, now - MAX_REACH_MS);
}

export interface KeyLineOptions {
  t0: number;
  t1: number;
  now: number;
  untouched: boolean;
  /** How many previous periods (of each kind) are drawn, newest first (default 1). */
  count?: number;
  /**
   * Whether the side of a level comes from the orderflow bias of its period (`biasState`, the same function the HTF candles and the
   * `trend-bias` table use) rather than from the period's body. The Pine's own switch (`trend_orderflow`, `OEC:2200-2211`): with it off
   * the side is `close > open`, exactly as the HTF candles fall back.
   */
  biasByOrderflow?: boolean;
  /**
   * The chart's bar size for the hierarchy gate: the day's, the week's and the month's lines are drawn by the Pine's own `showsPeriod`
   * (`previous-ohlc.ts`, `GlobalFunctions:192-197`), the same rule the eight frames of the block follow (T-1221). Absent or 0 draws every kind.
   */
  chartMs?: number;
  /** The chart's own bars, for the touch (T-1226): the Pine looks for it on every chart bar, not on the period's. Absent: the period bars. */
  touchBars?: readonly Bar[];
}

/**
 * Lines from exchange-native day/week/month bars: over each period that touches the chart, the previous completed
 * period's high, low and close. Untouched previous levels can extend past the next period until price reaches them.
 */
/** One period bar as the engines' `Bar`, for the orderflow comparison (volume is not read by it). */
const asBar = (b: PeriodBar): Bar => [b.openTime, b.open, b.high, b.low, b.close, 0];

/**
 * The side a level is painted with: the orderflow bias of the period against the one before it when the switch is on (`biasState`, the
 * HTF candles' own function), and its body otherwise (`close > open`), which is the Pine's two branches (`OEC:2200-2211`). A period with
 * nothing before it falls back to its body rather than inventing a bias.
 */
function sideOf(period: PeriodBar, before: PeriodBar | null, byOrderflow: boolean): 'bull' | 'bear' | 'neutral' {
  if (byOrderflow && before) {
    const state = biasState([asBar(before), asBar(period), asBar(period)]);
    if (state === 'bullish' || state === 'pre-bullish') return 'bull';
    if (state === 'bearish' || state === 'pre-bearish') return 'bear';
    if (state === 'neutral') return 'neutral';
  }
  return period.close > period.open ? 'bull' : period.close < period.open ? 'bear' : 'neutral';
}

export function keyLines(bars: PeriodBars, lines: Readonly<Record<PeriodKind, PeriodLines>>, o: KeyLineOptions): KeyLine[] {
  const out: KeyLine[] = [], end = Math.min(o.t1, o.now);
  if (!(end > o.t0)) return out;
  for (const period of PERIOD_KINDS) {
    const want = lines[period];
    // The row's own switch, then its three boxes: a row that is off draws nothing and keeps what its boxes said (T-1203).
    if (!want.on || (!want.high && !want.low && !want.close)) continue;
    // The hierarchy gate is the Pine's own, shared with the eight frames (T-1221): `day` asks as `pd`, `week` as `pw` and `month` as `pm`, so the
    // month is the one line that appears in both families (`show_below_equal_M`, true on everything but a seconds chart).
    if (o.chartMs && !showsPeriod(o.chartMs, PERIOD_FRAME[period])) continue;
    // The period under way, when the series brings none: an exchange series ends at the last **completed** bar (a month that has just closed, a
    // week whose Sunday bar is in). Without this, the newest close was never drawn at all — the loop draws `prev` over `cur`, and the last bar was
    // taken as the one under way (T-1228). It is opened at that bar's close and runs one period, as the next one would.
    const list = [...bars[period]];
    const lastBar = list[list.length - 1];
    if (lastBar?.complete && o.now >= lastBar.closeTime) {
      const span = Math.max(PERIOD_MS[period], lastBar.closeTime - lastBar.openTime);
      list.push({ openTime: lastBar.closeTime, closeTime: lastBar.closeTime + span, open: lastBar.close, high: lastBar.close, low: lastBar.close, close: lastBar.close, complete: false });
    }
    if (list.length < 2) continue;
    for (let i = 1; i < list.length; i++) {
      const prev = list[i - 1]!, cur = list[i]!;
      if (!prev.complete) continue;
      // Draw previous levels across the current period (and lookback periods that still touch the view).
      if (cur.closeTime <= o.t0 - PERIOD_MS[period] * LOOKBACK[period]) continue;
      if (cur.openTime > end) continue;
      // How many past periods are shown (of each kind), newest first. 1 draws the last completed period over the one under way (or over the
      // last one when the history has ended); 2 adds the one before it, and so on. The period under way never uses a slot up.
      const shown = Math.max(1, Math.min(MAX_PREVIOUS, o.count ?? 1)), newestPast = list.length - 2;
      if (i - 1 < newestPast - (shown - 1)) continue;
      const to = cur.closeTime, under = cur.closeTime > o.now;
      // A neutral close draws its high and its low whether or not their boxes are on (T-1222), the Pine's own gate
      // (`OEC:1539`/`:1545`/`:1554`: the box, or the orderflow switch with a neutral period).
      const neutralHL = o.biasByOrderflow === true && sideOf(prev, i >= 2 ? list[i - 2]! : null, true) === 'neutral';
      const levels: [LevelWhat, number][] = [];
      if (want.high || neutralHL) levels.push(['high', prev.high]);
      if (want.low || neutralHL) levels.push(['low', prev.low]);
      if (want.close) levels.push(['close', prev.close]);
      const newest = i - 1 === list.length - 2;
      for (const [what, price] of levels) {
        const line: KeyLine = {
          period, what, prev: true, price,
          // Where the line starts is the Pine's `_xt` (`OEC:1420`): the **previous** period's start for the high and the low (`_time` is
          // `daily_time_prev`, `:1539-1554`) and the current one's for the close (`daily_time`, `:1538`). Starting a touched low at the current
          // period made it one or two bars long, which is why the lows looked missing (T-1224).
          from: what === 'close' ? cur.openTime : prev.openTime, to,
          of: prev.openTime,
          window: `${period}|${cur.openTime}`,
          bias: sideOf(prev, i >= 2 ? list[i - 2]! : null, o.biasByOrderflow === true),
        };
        if (o.untouched && !under) {
          const hit = reachedAtBar(price, cur.openTime, list.slice(i));
          if (hit === null || hit >= cur.closeTime) line.reached = hit;
        }
        // The touch, on every bar of the period and not only while the line is drawn (T-1222): the Pine checks it in every bar (`OEC:1377-1390`).
        line.touched = o.touchBars ? touchedOnChart(o.touchBars, price, cur.openTime) : reachedAtBar(price, cur.openTime, list.slice(i));
        line.newest = newest;
        out.push(line);
      }
    }
  }
  return out.length > MAX_LINES ? out.sort((a, b) => a.from - b.from).slice(-MAX_LINES) : out;
}

export const lineEnd = (line: KeyLine): number => line.reached === undefined ? line.to : line.reached === null ? Infinity : line.reached;

/**
 * The candle size whose bars start on every period boundary of `zone` (for VWAP / volume-profile calendars — not key levels).
 */
export function barMsFor(zone: string, from: number, to: number): number {
  let bar = HOUR;
  for (let t = from; ; t = Math.min(to, t + 7 * DAY)) {
    const minutes = Math.round(offsetMs(zone, t) / MINUTE);
    if (minutes % 30 !== 0) return 15 * MINUTE;
    if (minutes % 60 !== 0) bar = 30 * MINUTE;
    if (t >= to) return bar;
  }
}

/** Zone calendar windows (VWAP / delta CVD resets / volume profile). Key levels use exchange candles instead. */
export function windowsOf(period: PeriodKind, zone: string, t0: number, t1: number): ProfileWindow[] {
  return period === 'day' ? dayWindows(zone, t0, t1) : period === 'week' ? weekWindows(zone, t0, t1) : monthWindows(zone, t0, t1);
}
