import type { Store } from '../store.ts';
import { LABEL_GAP } from '../labels.ts';
import { el } from '../dom.ts';
import { note, numberRow, selectRow, switchRow } from '../ui.ts';
import { helpButton } from '../help.ts';
import { t } from '../i18n.ts';
import { venueLabel } from '../venues.ts';
import { currentCoin } from '../coin.ts';

const DAY = 86_400_000;
import { MAX_BACK_MS, MAX_PREVIOUS, type PeriodKind } from './levels.ts';
import { DISPLAY_WORDS, MODE_WORDS, PREVIOUS_FRAMES, TEXT_WORDS, nextRowSetting, rowBoxes, rowIsOn } from './settings.ts';
import { historyTarget, type KeyLevelHistory } from './history.ts';
import { codeOf, periodDate } from './paint.ts';
import type { KeyLevelSettings, PreviousFrame, PreviousSettings } from './settings.ts';

/** A colour: the browser's own picker, so no palette has to be invented for the block's two (T-1186). */
function colorRow(name: string, what: string, value: string, onChange: (value: string) => void): HTMLElement {
  const box = el('input', { type: 'color', value });
  box.oninput = () => onChange(box.value);
  return el('label', { class: 'field', tip: what }, el('span', { class: 'label' }, el('span', { class: 'name', textContent: name }), el('span', { class: 'desc', textContent: what })), box);
}

/** The block's single table (T-1128): **eight** rows, the month at the top down to the minute, each with its own switch and its three boxes.
 *  The day, the week and the month are also drawn by the key levels' own lines, but that is the painter's business (T-1196/T-1201): this
 *  array is the order of the rows and nothing more. */
const FRAMES_ORDER: readonly PreviousFrame[] = ['pm', 'pw', 'pd', 'p4h', 'p1h', 'p15m', 'p5m', 'p1m'];
import { inspectorRows, sectionHead } from '../inspector.ts';

const PERIOD_NAMES: Readonly<Record<PeriodKind, string>> = { day: t('Day'), week: t('Week'), month: t('Month') };
/** The frames as the piece names them, in its own order. */
const FRAME_NAME: Readonly<Record<string, string>> = {
  p1m: t('Prev. 1m'), p5m: t('Prev. 5m'), p15m: t('Prev. 15m'), p1h: t('Prev. 1H'), p4h: t('Prev. 4H'), pd: t('Prev. Day'), pw: t('Prev. Week'), pm: t('Prev. Month'),
};
/**
 * The Key levels panel: its first row switches them on and off; then which lines of the day, the week and the month (a grid of boxes), whether an untouched level runs on, labels and axis tags, and whose candles they come from.
 */
export function buildKeyLevelPanel(store: Store, tools: HTMLElement, body: HTMLElement, rebuild: () => void, history: KeyLevelHistory | null): void {
  const s = store.state.keyLevels;
  const set = (change: Partial<KeyLevelSettings>, again = false): void => { store.set({ keyLevels: { ...store.state.keyLevels, ...change } }); if (again) rebuild(); };
  // One table for every frame (T-1128): the month at the top and the minute at the bottom, one switch a row and the same three lines each.
  // The day, the week and the month are the same rows as the rest — they are the frames `pd`, `pw` and `pm` —, so the panel never shows the
  // same three periods twice, and the numbers are the ones `previousLevels` already works out for the frames: no second way was added.
  const prev = s.previous;
  const setPrevious = (change: Partial<PreviousSettings>, again = true): void => {
    store.set({ keyLevels: { ...store.state.keyLevels, previous: { ...store.state.keyLevels.previous, ...change, touched: true } } });
    if (again) rebuild();
  };
  // One table, one row each level of the block (T-1202): the month at the top and the minute at the bottom, and every row has its own switch
  // and its own Close, High and Low. The day, the week and the month are the key levels' **own** lines, so their row writes those; the four
  // intraday rows are the frames' own. No row mirrors into another and no box switches a frame on.
  const table = el('div', { class: 'keylevel-grid', role: 'group', ariaLabel: t('Levels') },
    el('span', { class: 'head head-frame', textContent: t('Timeframe') }),
    el('span', { class: 'head', textContent: t('Cierre') }),
    el('span', { class: 'head', textContent: t('Máximo') }),
    el('span', { class: 'head', textContent: t('Mínimo') }));
  for (const frame of FRAMES_ORDER) {
    const name = FRAME_NAME[frame];
    // Every control of every row goes through `nextRowSetting` (T-1203): the panel holds no decision of its own, so a box cannot touch another
    // row and a switch cannot turn a box on.
    const on = el('input', { type: 'checkbox', checked: rowIsOn(frame, s), ariaLabel: name });
    on.onchange = () => set(nextRowSetting(frame, 'on', on.checked, store.state.keyLevels), true);
    // The whole name is the switch's label, so a press on the name flips the row (T-1206): a 15 px box alone is not a touch target.
    table.append(el('label', { class: 'what', tip: name }, el('span', { class: 'name' }, on, el('span', { textContent: name }))));
    const boxes = rowBoxes(frame, s);
    for (const line of ['close', 'high', 'low'] as const) {
      const box = el('input', { type: 'checkbox', checked: boxes[line], ariaLabel: `${name}${LABEL_GAP}${line}` });
      box.onchange = () => set(nextRowSetting(frame, line, box.checked, store.state.keyLevels), true);
      table.append(el('label', { tip: `${name}${LABEL_GAP}${line}` }, box));
    }
  }
  // No switch here: the piece's lamp in the bar is its switch (T-1304), and a second one would be two sources for one thing (T-1295).
  body.append(
    sectionHead(t('Levels')), table,
    // `keylevels_mode` and `keylevels_last` (`OddEyeCircle:84-85`): Present draws the last `last` periods, Historic every one the Pine allows
    // (`_cap`, `:943`). `last` replaces the old `count`, widened to the Pine's twenty, and a save that kept `count` reads as `last` (D-43).
    selectRow(t('Mode'), t('Present draws the last periods, Historic every one the block keeps.'), Object.keys(MODE_WORDS).map(value => [value, t(value)] as [string, string]), s.mode, value => set({ mode: value as KeyLevelSettings['mode'] })),
    numberRow(t('Periods'), t('How many previous periods of each kind are drawn, newest first: 1 draws only the last completed day, week and month; more reach further back.'), { min: 1, max: MAX_PREVIOUS, step: 1, value: s.last }, last => set({ last: Math.max(1, Math.min(MAX_PREVIOUS, Math.round(last))) })),
    numberRow(t('Levels opacity'), t('How opaque the previous levels are drawn, in percent. 100 % draws them solid; lower lets the candles and the heat show through.'), { min: 10, max: 100, step: 5, value: s.opacity ?? 100 }, opacity => set({ opacity: Math.max(10, Math.min(100, Math.round(opacity))) })),
    switchRow(t('Run on until reached'), t('A previous high, low or close that the next period never traded through stays on, dotted, until price reaches it.'), s.untouched, untouched => set({ untouched })),
    switchRow(t('Labels'), t('Each line\'s name and price at its right end, where there is room.'), s.labels, labels => set({ labels })),
    switchRow(t('Tags on the price axis'), t('The name of each line that reaches the right edge, beside its price.'), s.tags, tags => set({ tags })),
    // The Pine prints the date on a level that ran past its period; here it can be asked for every level (T-1197).
    switchRow(t('Dates on the levels'), t('The date of the period each level belongs to, beside its price.'), s.dates, dates => set({ dates })),
  );
  body.append(
    switchRow(t('Follow the chart timeframe'), t('Only the frames of the chart\'s own timeframe family are drawn; off, every frame.'), prev.follow, follow => setPrevious({ follow })),
    switchRow(t('Labels'), t('Each frame\'s name at the right end of its line, where there is room.'), prev.labels, labels => setPrevious({ labels })),
    switchRow(t('Price in the label'), t('The level\'s price beside its name. Off, the name alone.'), prev.prices, prices => setPrevious({ prices })),
    selectRow(t('Style'), t('The line style; Period keeps each period\'s dash.'), (['period', 'solid', 'dashed', 'dotted'] as const).map(value => [value, t(value === 'period' ? 'Period' : value === 'solid' ? 'Solid' : value === 'dashed' ? 'Dashed' : 'Dotted')] as [string, string]), prev.style, value => setPrevious({ style: value as KeyLevelSettings['previous']['style'] })),
    numberRow(t('Width'), t('How thick the frames\' lines are drawn.'), { min: 1, max: 5, step: 1, value: prev.width }, width => setPrevious({ width: Math.max(1, Math.min(5, Math.round(width))) })),
  );
  // The block's own ten, from the indicator (T-1186): they rule every line this panel draws, the day's, the week's, the month's and the
  // four intraday frames alike, so there is one look and not one per family.
  body.append(
    selectRow(t('Display'), t('Future runs on from the level; Right puts it at the right edge.'), Object.keys(DISPLAY_WORDS).map(value => [value, t(value)] as [string, string]), prev.displaystyle, value => setPrevious({ displaystyle: value as unknown as KeyLevelSettings['previous']['displaystyle'] })),
    numberRow(t('Anchor'), t('Candles past the last one where Right begins.'), { min: 0, max: 500, step: 1, value: prev.anchor }, anchor => setPrevious({ anchor: Math.max(0, Math.min(500, Math.round(anchor))) })),
    numberRow(t('Extend'), t('Candles past the last one where Right runs.'), { min: 5, max: 500, step: 1, value: prev.extend }, extend => setPrevious({ extend: Math.max(5, Math.min(500, Math.round(extend))) })),
    selectRow(t('Text'), t('The label\'s size.'), Object.keys(TEXT_WORDS).map(value => [value, t(value)] as [string, string]), prev.text, value => setPrevious({ text: value as unknown as KeyLevelSettings['previous']['text'] })),
    switchRow(t('Short'), t('The code alone, or the period named before it.'), prev.short, short => setPrevious({ short })),
    switchRow(t('Compact'), t('Two levels at one price are one line.'), prev.compact, compact => setPrevious({ compact })),
    switchRow(t('Orderflow in the compact label'), t('The orderflow side in the compact label.'), prev.compactOrderflow, compactOrderflow => setPrevious({ compactOrderflow })),
    switchRow(t('Fill the compact label with its colour'), t('Fill the compact label with its colour.'), prev.fillOrderflow, fillOrderflow => setPrevious({ fillOrderflow })),
    // T-1246: `keylevels_plot_style` (`OddEyeCircle:150`). El tercer valor se llama Combinado por el KENJI (`:857`); el Pine lo llama
    // `Fill + Markers` y es el mismo. El default es Combinado (decisión del usuario), no el `Fill` del Pine.
    selectRow(t('Sweep style'), t('Where HTF 1 breaks HTF 2\'s previous close and closes back: the area, the marks, or both.'), [['both', t('Combined')], ['fill', t('Fill')], ['markers', t('Marks')]] as [string, string][], prev.sweepStyle, value => setPrevious({ sweepStyle: value as KeyLevelSettings['previous']['sweepStyle'] })),
    colorRow(t('Bullish'), t('The bullish colour.'), prev.bullColor, (bullColor: string) => setPrevious({ bullColor })),
    colorRow(t('Bearish'), t('The bearish colour.'), prev.bearColor, (bearColor: string) => setPrevious({ bearColor })),
  );
  // The colour of each frame, the Pine's own eight (`intra1m_css` … `monthly_css`, `OddEyeCircle:104,109,114,119,124,129,134,139`): the line a frame draws keeps its
  // colour unless the orderflow tone paints over it, so the two switches above do not cover them.
  body.append(sectionHead(t('Colours of the frames')));
  for (const frame of PREVIOUS_FRAMES) {
    const name = FRAME_NAME[frame] ?? frame;
    body.append(colorRow(name, t('The colour of the {frame} levels.', { frame: name }), prev.colors[frame], (color: string) => setPrevious({ colors: { ...prev.colors, [frame]: color } })));
  }
  const target = historyTarget(store.state.marketId, currentCoin());
  if (!target) { body.append(note(t('No market of this coin has a history the page can read, so there are no key levels.'))); inspectorRows(body); return; }
  body.append(note(t('From {market}\'s own daily, weekly and monthly candles (the exchange\'s 1d / 1w / 1M opens), about two months of them.', { market: `${venueLabel(target.id)} ${target.listing.symbol}` })));
  if (!target.own) body.append(note(t('The market on the chart has no history the page can read, so another market of the coin is used; its prices can differ a little.')));
  if (history?.id === target.id && history.state === 'unavailable') body.append(note(t('Its history could not be read just now; trying again in a minute.')));
  // A history that begins later than the two months the lines can reach (a young listing, or OKX's shorter pages for a zone off the hour).
  else if (history?.id === target.id && history.state === 'ready' && history.heldFrom > Date.now() - MAX_BACK_MS + 3 * DAY) body.append(note(t('Its history reaches back to {date} only, so lines of earlier periods are missing.', { date: periodDate(history.heldFrom, 'day', 'UTC') })));
  inspectorRows(body);
}
