import type { Bar } from '../../engine/series/source.ts';
import { PREVIOUS_OHLC, previousLevels, type PreviousLevel } from '../../indicators/previous-ohlc.ts';
import type { InputValues } from '../../engine/inputs/schema.ts';
import type { CandleRow } from '../store.ts';
import { readInputs } from '../../engine/inputs/schema.ts';
import { PERIOD_FRAMES, DRAWN_FRAMES, PREVIOUS_FRAMES, type PreviousSettings } from './settings.ts';
import { showsPeriod } from '../../indicators/previous-ohlc.ts';

/**
 * The previous-OHLC frames the key levels draw (T-1079): the numbers come from `previousLevels` —the piece's own function, not a copy— and
 * from here they reach the painter, which no longer asks the study. The series are the page's own: the four intradaily ones and the day,
 * the week and the month, loaded by the key levels' history loader and handed in whole.
 *
 * Nothing is computed per frame: whoever owns the loader calls `setPreviousFrames` when its series move, and the painter only reads.
 */
let frames: readonly PreviousLevel[] = [];
export const previousFrames = (): readonly PreviousLevel[] => frames;

/** The frames for a `now`, from the series the caller holds: a series it does not have contributes nothing (never a level from another). */
export function previousFramesFrom(series: ReadonlyMap<string, readonly CandleRow[]>, params: InputValues, chartMs: number, now: number): PreviousLevel[] {
  const barsOf = (tf: string): readonly Bar[] | null => {
    const rows = series.get(tf);
    return rows && rows.length ? rows.map(row => [row[0], row[1], row[2], row[3], row[4], row[5]] as Bar) : null;
  };
  // Never the day, the week or the month, whoever built the params (T-1197): the key levels draw those three themselves.
  return previousLevels(now, barsOf, withoutPeriodFrames(params), chartMs);
}

/** Hand the painter the frames just worked out. */
export function setPreviousFrames(next: readonly PreviousLevel[]): void { frames = next; }


/**
 * The piece's inputs as this panel sets them (T-1079): the eight frames' switches, the three levels each, the hierarchy, the labels, the price
 * in them, the dash and the width. Read through `readInputs`, so the ranges and the defaults are the piece's own and not repeated here.
 */
export function paramsFromSettings(previous: PreviousSettings): InputValues {
  // The family switch governs (the user's decision, 2026-11-08): on —the Pine's default and what the panel shows— only the frames of the chart
  // timeframe's family are drawn; off, every frame the panel switches on. The switch lives in the panel and this is what it does, measured by
  // `tests/app-previous-settings.test.mts` in both positions.
  const raw: Record<string, unknown> = {
    open: false, mid: false, hierarchy: previous.follow, labels: previous.labels, prices: previous.prices, style: previous.style, width: previous.width,
    // The block's own ten (T-1186): the Pine's display, its distances, the label's size and word, the compact pair and its two colours.
    displaystyle: previous.displaystyle, anchor: previous.anchor, extend: previous.extend, text: previous.text, short: previous.short,
    compact: previous.compact, compactOrderflow: previous.compactOrderflow, fillOrderflow: previous.fillOrderflow,
    bullColor: previous.bullColor, bearColor: previous.bearColor,
  };
  for (const frame of PREVIOUS_FRAMES) {
    // The Pine's own colour of the frame (`intra1m_css` … `monthly_css`): the piece reads it from `${id}.color` and the panel is where it is
    // set now (T-1079 moved the block here), so it has to be handed over with the rest or the piece keeps its default for ever (T-1298).
    raw[`${frame}.color`] = previous.colors[frame];
  }
  for (const frame of DRAWN_FRAMES) {
    raw[`${frame}.on`] = previous.frames[frame];
    raw[`${frame}.high`] = previous.levels[frame].high;
    raw[`${frame}.low`] = previous.levels[frame].low;
    raw[`${frame}.close`] = previous.levels[frame].close;
  }
  return withoutPeriodFrames(readInputs(PREVIOUS_OHLC.inputs, raw));
}

/**
 * The day, the week and the month belong to the key levels' own lines (T-1197): the previous-OHLC route never draws them, whatever a save says,
 * because both routes drawing them put the previous day on the chart twice. Their panel rows still switch the key levels' lines on and off.
 */
export function withoutPeriodFrames(params: InputValues): InputValues {
  const out: Record<string, unknown> = { ...params };
  for (const frame of PERIOD_FRAMES) out[`${frame}.on`] = false;
  return out as InputValues;
}

/**
 * Which settings rule: this panel's once somebody has used it, and until then whatever the piece kept in `studyParams['previous-ohlc']` — a
 * save from before T-1079 keeps the frames it had, and nothing is quietly overwritten by the new defaults.
 */
export function paramsFor(previous: PreviousSettings, saved: InputValues | null): InputValues {
  return withoutPeriodFrames(!previous.touched && saved ? readInputs(PREVIOUS_OHLC.inputs, saved) : paramsFromSettings(previous));
}

/**
 * El **cierre previo de HTF 2** que barre este port (T-1246): el marco más grueso que la jerarquía dibuja, sin contar el mes —que tiene su
 * propio trato (`previous-ohlc.ts:235`)—, y sólo si ese marco trae su nivel de cierre.
 *
 * La regla no es inventada aquí: la jerarquía es la del Pine (`showsPeriod`, `GlobalFunctions:192-197`) y es la del usuario, «5m → 1H y D,
 * 15m → 4H y W para los dos HTF»: con un gráfico de 15m el marco más grueso que se dibuja es la semana, y con uno de 5m el día, que es
 * exactamente el segundo de los dos HTF en cada caso. El Pine lo elige con `tf_htf_2`, un input que este port no tiene.
 */
const COARSEST_FIRST = ['pw', 'pd', 'p4h', 'p1h', 'p15m', 'p5m', 'p1m'] as const;

export function previousSweepLevel(chartMs: number): number | null {
  if (!(chartMs > 0)) return null;
  const closes = new Map<string, number>();
  for (const level of frames) if (level.what === 'close') closes.set(level.frame, level.price);
  for (const frame of COARSEST_FIRST) {
    if (!showsPeriod(chartMs, frame)) continue;
    const price = closes.get(frame);
    if (price !== undefined && Number.isFinite(price)) return price;
  }
  return null;
}
