/**
 * What a press would reach (T-1130): the one line the user's console needed. A control that does not answer is either not wired — and the
 * handlers are all set at boot — or something lies over it. This probes the centre of the controls people press and says what is on top,
 * once, so "nothing happens" becomes "this element is over that button".
 */
export interface HitReport {
  readonly selector: string;
  /** A word for what was found: the control itself, something inside it, or what covers it. */
  readonly over: 'self' | 'child' | 'covered' | 'missing';
  /** The covering element, when there is one: `tag.class`. */
  readonly by?: string;
  /** Why it covers, when that can be said: a **neighbour's** arm (the 44 px touch area, a `::after`) or a **layer** over the control. */
  readonly why?: 'neighbour' | 'layer';
}

/** A short name for an element, as a console line or a test can hold: `tag.class`, or the tag alone. */
export function describeElement(node: Element | null): string | null {
  if (!node) return null;
  const name = node.tagName.toLowerCase();
  const classes = [...node.classList].slice(0, 2).join('.');
  return classes ? `${name}.${classes}` : name;
}

/** What a press at the centre of `control` would reach, given what `elementFromPoint` answered there. */
export function hitOf(control: Element | null, top: Element | null): HitReport['over'] {
  if (!control) return 'missing';
  if (!top) return 'covered';
  if (top === control) return 'self';
  return control.contains(top) ? 'child' : 'covered';
}

/**
 * Why one element lands on top of another (T-1130): a control that shares its parent with the covered one is a **neighbour** — the touch
 * area grown with a pseudo-element reaches into it — and anything else is a **layer** over the control (a canvas, a panel, a tip).
 */
export function whyCovered(control: Element, top: Element | null): 'neighbour' | 'layer' {
  if (!top) return 'layer';
  return top.parentElement !== null && top.parentElement === control.parentElement ? 'neighbour' : 'layer';
}

/** Probes one control by selector: where its centre lands, and what is on top of it. */
export function probeControl(doc: Document, selector: string): HitReport {
  const control = doc.querySelector(selector);
  if (!control) return { selector, over: 'missing' };
  const box = control.getBoundingClientRect();
  // A control with no box (not shown, or on a tab that is not the current one) cannot be pressed and is not a covering problem.
  if (box.width < 1 || box.height < 1) return { selector, over: 'missing' };
  const top = doc.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2);
  const over = hitOf(control, top);
  return over === 'covered' ? { selector, over, by: describeElement(top) ?? 'unknown', why: whyCovered(control, top) } : { selector, over };
}

/** Probes the controls the person presses and says only what is wrong, once: a covered control is a bug, a missing one is a hidden tab. */
export function reportCoveredControls(doc: Document, selectors: readonly string[]): HitReport[] {
  const covered = selectors.map(selector => probeControl(doc, selector)).filter(report => report.over === 'covered');
  // Codes, not a sentence: this is a diagnostic to paste into a report, and a sentence a person reads would have to live in the packs.
  for (const report of covered) console.info(`[hits] ${report.selector} <- ${report.by} (${report.why})`);
  return covered;
}
