/**
 * The worst-case dataset of the panel pass (T-1178): a switch for **development only**, so the panel can be looked at with the ugliest
 * realistic data there is — a long instrument beside a short one, a counter of four digits and one of exactly one, a session name that is
 * a sentence, prices with six decimals.
 *
 * It enters by the same door as the good data: `studyReadout` (what the pieces publish) and the store's market, never by touching the
 * markup. `import.meta.env.DEV` is false in a build, so nothing of this ships: a published page cannot open it.
 */
import { t } from '../i18n.ts';
import type { ReadoutRow } from '../../engine/studies/contract.ts';

/** Whether this page was opened with `?adverse=1`, in a development build only. */
export function adverseOn(): boolean {
  if (!import.meta.env.DEV) return false;
  try { return adverseMode() !== null; } catch { return false; }
}

/** Which dataset: `1` (the long one), `empty` (a piece that publishes no row at all) or `single` (a plan with one target and no ladder). */
export function adverseMode(): '1' | 'empty' | 'single' | 'stress' | null {
  if (!import.meta.env.DEV) return null;
  try {
    const value = new URLSearchParams(window.location.search).get('adverse');
    return value === '1' || value === 'empty' || value === 'single' || value === 'stress' ? value : null;
  } catch { return null; }
}

/** A long exchange id (`okx:BTC-USDT-SWAP`) with a short one borrowed beside it (`BTCUSD`), both real instruments. */
export const ADVERSE_MARKET = 'okx:BTC-USDT-SWAP';
export const ADVERSE_BORROWED = 'BTCUSD';

/** The session name the plan head shows: long, hyphenated, and the kind of thing the cycle actually produces. */
const ADVERSE_SESSION = 'asia-pacific-afternoon-session-extended-extra-long';
/** The same id taken past any length the layout can hold: the case the ellipsis is for. */
const STRESS_SESSION = 'asia-pacific-afternoon-session-extended-extra-long-and-then-some-more-characters-to-force-it';

/**
 * The readout the pieces would publish for this dataset, or `null` for a piece this switch does not touch. Two cases in one:
 * `st-entry` gives a plan whose prices carry six decimals and whose ladder has one level only (`tpLp`), so five of the six targets are
 * dashes; `trend-bias` gives an empty table, which is the "no rows at all" the panel has to survive.
 */
export function adverseReadout(id: string): readonly ReadoutRow[] | null {
  if (id === 'trend-bias') return [];
  if (id !== 'st-entry') return null;
  const mode = adverseMode();
  // The two list extremes the pass asks for: no row at all (the piece has nothing to say) and one row with one value.
  if (mode === 'empty') return [];
  if (mode === 'single') return [{ id: 'st:bear:london', label: t('Trade plan'), values: [{ id: 'state', value: 'tp1-wait' }, { id: 'tp1', value: 98_100.5 }] }];
  if (mode === 'stress') return [{
    id: `st:bull:${STRESS_SESSION}`,
    label: t('Trade plan'),
    values: [
      { id: 'state', value: 'armed' },
      { id: 'entry', value: 1_284_999.754321 },
      { id: 'stop', value: 1_100_100.5 },
      { id: 'tpLp', value: 1_284_000.25 },
      { id: 'tp1', value: 1_286_004.5 },
      { id: 'tp2', value: 1_290_000.75 },
    ],
  }];
  return [{
    id: `st:bull:${ADVERSE_SESSION}`,
    label: t('Trade plan'),
    values: [
      { id: 'state', value: 'armed' },
      { id: 'entry', value: 104_982.123456 },
      { id: 'stop', value: 99_100.5 },
      { id: 'riskStop', value: 98_761.987654 },
      { id: 'tpLp', value: 105_240.25 },
      // One target of six: the rest come back as dashes, never as a made-up number.
      { id: 'tp1', value: 106_004.5 },
    ],
  }];
}
